// Confirma que el aviso viene del portal y arma el correo (texto + HTML).
const ESPERADO = 'cambiar-por-una-clave-larga';   // la misma que N8N_WEBHOOK_SECRET en el .env del portal
const item = $input.first().json;
const token = (item.headers || {})['x-portal-token'] || '';
if (ESPERADO && token !== ESPERADO) {
  throw new Error('El aviso no trae la clave compartida correcta: se descarta.');
}
const b = item.body || {};
const o = b.order || {};
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const cambio = o.type === 'codigo' ? `${o.from} → ${o.to}` : `Reemplazos de ${o.code}`;
const fila = (k, v) => v ? `<tr><td style="padding:6px 0;color:#6b7280;font-size:13px;width:130px">${k}</td><td style="padding:6px 0;font-size:14px">${v}</td></tr>` : '';
let asunto, titulo, texto, filas = '', url = o.url || b.portal_url || '';
if (b.event && b.event.startsWith('pedido') && o.id) {
  titulo = b.action;
  asunto = `Portal SERVELEC: pedido #${o.id} — ${b.action.toLowerCase()}`;
  texto = `Pedido #${o.id} (${cambio}): ${b.action}. Estado: ${o.status}. Lo pidió ${o.requested_by}` +
          (o.decided_by ? `, lo aprobó ${o.decided_by}` : '') + `. ${url}`;
  filas = fila('Pedido', `#${esc(o.id)}`) + fila('Cambio', `<b>${esc(cambio)}</b>`) + fila('Estado', esc(o.status)) +
          fila('Lo pidió', esc(o.requested_by)) + fila('Decidió', esc(o.decided_by)) + fila('Motivo', esc(o.reason)) +
          (o.planned ? fila('Alcance', `${o.planned.cells} celdas en ${o.planned.files} archivos`) : '') +
          (o.result ? fila('Resultado', `${o.result.changes} cambios en ${o.result.files} archivos` + (o.result.failed ? ` · ${o.result.failed} con error` : ''))
                    : '');
} else {
  titulo = b.action;
  asunto = `Portal SERVELEC: ${b.action.toLowerCase()}`;
  texto = b.action + (b.detail ? ' — ' + b.detail : '');
  filas = fila('Qué pasó', esc(b.action)) + fila('Detalle', esc(b.detail)) + fila('Quién', esc(b.by));
}
const html = `
<div style="font-family:Segoe UI,Arial,sans-serif;max-width:560px;margin:0 auto;color:#111827">
  <div style="background:#1e3a5f;color:#fff;padding:16px 22px;border-radius:10px 10px 0 0">
    <div style="font-size:12px;opacity:.8;letter-spacing:.04em">PORTAL DE DOCUMENTACIÓN · SERVELEC</div>
    <div style="font-size:19px;font-weight:600;margin-top:4px">${esc(titulo)}</div>
  </div>
  <div style="border:1px solid #e5e7eb;border-top:0;padding:16px 22px 20px;border-radius:0 0 10px 10px">
    <table style="border-collapse:collapse;width:100%">${filas}</table>
    ${url ? `<p style="margin:18px 0 0"><a href="${esc(url)}" style="background:#1e3a5f;color:#fff;text-decoration:none;padding:10px 18px;border-radius:6px;font-size:14px;display:inline-block">Abrir en el portal</a></p>` : ''}
  </div>
</div>`;
return [{ json: { evento: b.event, asunto, texto, html, pedido: o, original: b } }];
